import threading

# the broken version: barrier forces both reads before either write
counter = [0]
barrier = threading.Barrier(2)

def add_unlocked():
    seen = counter[0]
    barrier.wait()
    counter[0] = seen + 1

threads = [threading.Thread(target=add_unlocked) for _ in range(2)]
for t in threads: t.start()
for t in threads: t.join()
print("unlocked, forced schedule:", counter[0])

# the locked version: the whole read-modify-write is one indivisible step
locked_counter = [0]
lock = threading.Lock()

def add_locked():
    for _ in range(500):
        with lock:
            locked_counter[0] += 1

threads = [threading.Thread(target=add_locked) for _ in range(2)]
for t in threads: t.start()
for t in threads: t.join()
print("locked, 2 threads x 500:", locked_counter[0])

import threading

cache_hits = [0]
stats_views = [0]
cache_lock = threading.Lock()
stats_lock = threading.Lock()

def hit_cache():
    for _ in range(400):
        with cache_lock:
            cache_hits[0] += 1

def view_stats():
    for _ in range(300):
        with stats_lock:
            stats_views[0] += 1

threads = ([threading.Thread(target=hit_cache) for _ in range(2)] +
           [threading.Thread(target=view_stats) for _ in range(2)])
for t in threads: t.start()
for t in threads: t.join()

