print("stats views:", stats_views[0], "(2 threads x 300)")

import queue
import threading

jobs = queue.Queue()
results = {}
results_lock = threading.Lock()

for n in range(1, 10):
    jobs.put(n)
for _ in range(3):
    jobs.put(None)   # one sentinel per worker

def worker():
    while True:
        n = jobs.get()
        if n is None:
            jobs.task_done()
            return
        with results_lock:
            results[n] = n * n
        jobs.task_done()

threads = [threading.Thread(target=worker) for _ in range(3)]
for t in threads: t.start()
jobs.join()
for t in threads: t.join()

print("jobs completed:", len(results))
print("results by job: ", [results[n] for n in range(1, 10)])
print("sum of squares:", sum(results.values()))

from concurrent.futures import ThreadPoolExecutor

def job(name, fail=False):
    if fail:
        raise ValueError(name + " failed")
    return name + " done"

with ThreadPoolExecutor(max_workers=2) as pool:
    futures = {"alpha": pool.submit(job, "alpha"),
               "beta": pool.submit(job, "beta", fail=True),
               "gamma": pool.submit(job, "gamma")}
    for name, future in futures.items():
        try:
            print(name, "->", future.result())
        except ValueError as e:
            print(name, "-> caught:", type(e).__name__, "-", e)

class FakeService:
    def __init__(self):
        self.calls = 0
    def call(self):
        self.calls += 1
        if self.calls < 3:
            raise ConnectionError("attempt " + str(self.calls) + " failed")
        return "payload"

def call_with_retry(service, max_attempts=4):
    delays = []            # virtual delays: recorded, not slept
    delay = 1.0
    for attempt in range(1, max_attempts + 1):
        try:
            return service.call(), attempt, delays
        except ConnectionError:
            if attempt == max_attempts:
                raise
            delays.append(delay)
            delay *= 2     # exponential backoff: 1, 2, 4, ...

service = FakeService()
result, attempts, delays = call_with_retry(service)
print("result:", result)
print("attempts used:", attempts)
print("virtual delays between attempts:", delays)

class AlwaysDown:
    def __init__(self):
        self.calls = 0
    def call(self):
        self.calls += 1
        raise ConnectionError("service unreachable")

def call_with_retry(service, max_attempts=3):
    delays = []
    delay = 1.0
    last_error = None
    for attempt in range(1, max_attempts + 1):
        try:
            return service.call(), delays
        except ConnectionError as e:
            last_error = e
            if attempt < max_attempts:
                delays.append(delay)
                delay *= 2
    raise last_error   # exhaustion is reported, never disguised

service = AlwaysDown()
try:
    call_with_retry(service)
    print("unexpected success")
except ConnectionError as e:
    print("gave up after attempts:", service.calls)
    print("virtual delays waited:", [1.0, 2.0])
    print("caller sees:", type(e).__name__, "-", e)

