import queue
import threading

inbox = queue.Queue()
result_q = queue.Queue()
state_writers = []

def owner():
    state = {}
    while True:
        message = inbox.get()
        if message is None:
            inbox.task_done()
            result_q.put(state)   # publish the final state before exiting
            return
        kind, key, value = message
        state_writers.append(threading.current_thread().name)
        if kind == "add":
            state[key] = state.get(key, 0) + value
        inbox.task_done()

owner_thread = threading.Thread(target=owner, name="state-owner")
owner_thread.start()

def client(adds):
    for key, value in adds:
        inbox.put(("add", key, value))

clients = [threading.Thread(target=client, args=(adds,))
           for adds in [[("hits", 100)], [("hits", 23), ("misses", 4)],
                        [("hits", 7)]]]
for c in clients: c.start()
for c in clients: c.join()
inbox.put(None)
owner_thread.join()
final_state = result_q.get()

print("distinct threads that wrote the state:", set(state_writers))
print("final state, as published by the owner:", final_state)

class Watchdog:
    def __init__(self, timeout):
        self.timeout = timeout
        self.last_beat = 0

    def beat(self, now):
        self.last_beat = now

    def check(self, now):
        return now - self.last_beat <= self.timeout

watchdog = Watchdog(timeout=25)
# scripted timeline on a virtual clock: beats at 0, 10, 20, then silence
beats = {0, 10, 20}
verdicts = []
for tick in range(0, 61, 5):
    if tick in beats:
        watchdog.beat(tick)
    verdicts.append((tick, watchdog.check(tick)))

for tick, alive in verdicts:
    print("tick", tick, "->", "alive" if alive else "DEAD")

import asyncio

async def main():
    never = asyncio.Event()

    async def process(item):
        if item == "stuck":
            await never.wait()          # this item hangs forever
        await asyncio.sleep(0)
        return item.upper()

    outcomes = []
    for item in ["alpha", "stuck", "beta"]:
        try:
            result = await asyncio.wait_for(process(item), timeout=0.05)
            outcomes.append((item, "ok: " + result))
        except asyncio.TimeoutError:
            outcomes.append((item, "TIMEOUT - skipped"))

    for item, outcome in outcomes:
        print(item, "->", outcome)

asyncio.run(main())

class CircuitBreaker:
    def __init__(self, failure_threshold):
        self.threshold = failure_threshold
        self.failures = 0
        self.open = False

    def call(self, fn):
        if self.open:
            return "REJECTED (breaker open)"
        try:
            result = fn()
        except ConnectionError:
            self.failures += 1
            if self.failures >= self.threshold:
                self.open = True
            return "FAILED"
        self.failures = 0
        return result

class DownService:
    def __init__(self):
        self.invocations = 0
    def request(self):
        self.invocations += 1
        raise ConnectionError("down")

service = DownService()
breaker = CircuitBreaker(failure_threshold=3)
verdicts = [breaker.call(service.request) for _ in range(5)]
print("verdicts:", verdicts)
print("times the service was actually invoked:", service.invocations)

class BatchingCollector:
    def __init__(self, max_size, max_wait):
        self.max_size = max_size
        self.max_wait = max_wait
        self.current = []
        self.first_at = None
        self.batches = []

    def offer(self, item, now):
        if self.current and now - self.first_at >= self.max_wait:
            self.flush()                      # time trigger, checked on arrival
        if not self.current:
            self.first_at = now
        self.current.append(item)
        if len(self.current) == self.max_size:
            self.flush()                      # size trigger

    def flush(self):
        if self.current:
            self.batches.append(self.current)
            self.current = []
            self.first_at = None

collector = BatchingCollector(max_size=3, max_wait=10)
arrivals = [(0, "a"), (1, "b"), (2, "c"),      # fills by size at t=2
            (3, "d"), (20, "e"),               # 'e' arrives 17 after 'd': time flush of [d]
            (21, "f"), (22, "g")]              # partial tail
for now, item in arrivals:
    collector.offer(item, now)
collector.flush()                              # end-of-stream flush

print("batches:", collector.batches)
print("sizes:  ", [len(b) for b in collector.batches])

class Throttle:
    def __init__(self, interval):
        self.interval = interval
        self.last_fired = None

    def fire(self, now):
        if self.last_fired is None or now - self.last_fired >= self.interval:
            self.last_fired = now
            return True
        return False

throttle = Throttle(interval=2.0)
attempts = [0.0, 0.5, 1.0, 1.9, 2.0, 2.5, 4.0]
print("attempts:", attempts)
print("fired:   ", [throttle.fire(t) for t in attempts])

import threading

class Counter:
    """The lock lives inside, with the state. There is no other way in."""
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    def add(self, n):
        with self._lock:
            self._value += n

    def value(self):
        with self._lock:
            return self._value

counter = Counter()

def worker():
    for _ in range(300):
        counter.add(1)

threads = [threading.Thread(target=worker) for _ in range(3)]
for t in threads: t.start()
for t in threads: t.join()

print("counter via its methods only:", counter.value())
print("expected:", 3 * 300)

class Breaker:
    def __init__(self, threshold):
        self.threshold = threshold
        self.failures = 0
        self.open = False
    def allow(self):
        return not self.open
    def on_success(self):
        self.failures = 0
    def on_failure(self):
        self.failures += 1
        if self.failures >= self.threshold:
            self.open = True

class FlakyService:
    def __init__(self):
        self.calls = 0
    def request(self):
        self.calls += 1
        if self.calls <= 6:
            raise ConnectionError("down")
        return "recovered payload"

def call_with_policy(service, breaker, max_attempts=2):
    if not breaker.allow():
        return "REJECTED by open breaker"
    for attempt in range(max_attempts):
        try:
            result = service.request()
            breaker.on_success()
            return result
        except ConnectionError:
            continue
    breaker.on_failure()     # ONE failure recorded per logical call
    return "FAILED after retries"

service = FlakyService()
breaker = Breaker(threshold=3)
outcomes = [call_with_policy(service, breaker) for _ in range(5)]
print("logical call outcomes:", outcomes)
print("raw service invocations:", service.calls)
print("breaker open at the end:", breaker.open)
